let source = msg.topic;
let val = msg.payload;
let ledState = flow.get("LEDState");

if (val == undefined) {
    val = 560; // or whatever initial value you want
    flow.set("adc", val);
}

let dutyCycle = (1 - (val - 454) / (990 - 454)) * 100; //Scales ADC value between 0-100 for PWM duty cycle.
let plcValue = Math.round(dutyCycle);

if (plcValue < 10) plcValue  = 0; // Fully Off
if (plcValue > 90) plcValue  = 100; // Fully On


if (ledState == "manual" && source == "override") {
    var msg1 = {payload: msg.payload.toString()}; //Remove this after implement auto
    plcValue = { payload: plcValue};

    return [msg1, plcValue];
}

else if (ledState == "auto" && source == "adc"){
    var msg1 = { payload: msg.payload.toString()};   
    plcValue = { payload: plcValue };

    return [msg1, plcValue];
}
return null;

let brightness = flow.get("brightness");
let dhpstate = flow.get("dhpState");
let miststate = flow.get("mistState");
let lastaction = flow.get("lastAction");
let temperature = flow.get("temp");
let humidity = flow.get("hum");
node.warn({
    brightness,
    dhpstate,
    miststate,
    lastaction,
    temperature,
    humidity
});

if (brightness != undefined && dhpstate != undefined && miststate != undefined && lastaction != undefined && temperature != undefined && humidity != undefined) {
    msg.payload = {
        studentid: 0,
        nickname: "ENCLOSURE STATUS",
        temp: temperature,
        hum: humidity,
        rain: brightness,
        windspeed: dhpstate ? 1 : 0,
        winddir: miststate ? 1 : 0,
        message: lastaction,
        valid: true,
    }
    return msg;
} else {
    return null;
}

let lastAction = msg.payload;

switch (lastAction) {
    case "aDHPon":
        flow.set("lastAction", "Auto DHP ON");
        flow.set("dhpState", 1);
        break;

    case "aDHPoff":
        flow.set("lastAction", "Auto DHP OFF");
        flow.set("dhpState", 0);
        break;

    case "mDHPon":
        flow.set("lastAction", "Override DHP ON");
        flow.set("dhpState", 1);
        break;

    case "mDHPoff":
        flow.set("lastAction", "Override DHP OFF");
        flow.set("dhpState", 0);
        break;

    case "aMist":
        flow.set("lastAction", "Auto Mist Cycle Completed");
        flow.set("mistState", 0);
        break;

    case "mMiston":
        flow.set("lastAction", "Override Mist ON");
        flow.set("mistState", 1);
        break;

    case "mMistoff":
        flow.set("lastAction", "Override Mist OFF");
        flow.set("mistState", 0);
        break;
}
return null;

let mode = msg.payload
let lastLEDmode = flow.get("LEDState");

if (mode != lastLEDmode) {
    if (mode == true) {
        flow.set("LEDState", "manual");
        flow.set("lastAction", "LED OVERRIDE");
    }

    if (mode == false) {
        flow.set("LEDState", "auto");
        flow.set("lastAction", "LED AUTO");
    }
}
return null;

if (flow.get("DHPMode") != "auto") return null;

let DHP = flow.get("temp");
let lastDHP = flow.get("lastDHP");

if (DHP != lastDHP) {
    if (DHP > 29) {
        lastDHP = flow.set("lastDHP", DHP);
        flow.set("lastAction", "Auto DHP OFF");
        return [{payload: "aDHPoff" }, null];
    }
    if (DHP < 27) {
        lastDHP = flow.set("lastDHP", DHP);
        flow.set("lastAction", "Auto DHP ON");
        return [null, {payload: "aDHPon" }];
    }
}

return [null, null];

